const labels={draft:'Afventer din godkendelse i e-conomic',booked:'Bogført i e-conomic',needs_attention:'Kræver manuel afklaring',creating_customer:'Kundeoprettelse afventer afstemning',creating_draft:'Kladdeoprettelse afventer afstemning'};
function el(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
export function invoiceSetupPanel(api){const box=el('section',undefined,'panel invoice-setup');box.append(el('h2','Fakturaer · manuel godkendelse'),el('p','Shoppen kan oprette kladder. Du gennemgår og bogfører dem selv i e-conomic. En kladde sendes aldrig som en færdig faktura til kunden.'));
 const status=el('p','Kontrollerer forbindelsen…','muted');box.append(status);api('/api/admin/invoices/status').then(r=>r.json()).then(config=>{status.textContent=config.ready?'Kladdeintegration aktiveret. Nye liveordrer behandles automatisk; bogføring sker manuelt.':'e-conomic er ikke tilsluttet endnu. API-adgang, kundegruppe, momszone, betalingsvilkår, varer og layout skal færdigopsættes før kladder kan oprettes.';}).catch(()=>{status.textContent='Forbindelsesstatus kunne ikke hentes.';});
 const link=el('a','Åbn e-conomic →','action light');link.href='https://secure.e-conomic.com/';link.target='_blank';link.rel='noopener noreferrer';box.append(link);return box;}
export function invoiceOrderPanel(order,api,onRefresh,onError){const box=el('div',undefined,'invoice-panel'),invoice=order.invoice;box.append(el('strong','Faktura · manuel godkendelse'),el('small',labels[invoice?.status]||(order.paymentMode==='live'?'Afventer e-conomic-opsætning eller næste synkronisering':'Afventer en bekræftet liveordre – testbetalinger faktureres ikke')));
 if(invoice?.draftInvoiceNumber)box.append(el('small',`Kladde nr. ${invoice.draftInvoiceNumber}`));if(invoice?.bookedInvoiceNumber)box.append(el('small',`Faktura nr. ${invoice.bookedInvoiceNumber}`));if(invoice?.error)box.append(el('small',invoice.error,'status pending'));
 if(order.paymentMode==='live'&&['authorized','paid'].includes(order.status)){const button=el('button','Opdatér fakturastatus','action light');button.type='button';button.onclick=async()=>{button.disabled=true;try{await api(`/api/admin/checkouts/${order.id}/invoice`,'POST',{});await onRefresh();}catch(error){onError(error.message);}finally{button.disabled=false;}};box.append(button);}
 if(order.status==='cancelled'&&invoice)box.append(el('small','Ordren er annulleret. Afklar kladden eller en eventuel kreditnota manuelt i e-conomic.','status pending'));
 if(invoice?.status==='draft')box.append(el('small','Kontrollér fakturaadresse, beløb, moms og kortbetalingen, og bogfør kladden i e-conomic. Shoppen bogfører ikke for dig.'));
 return box;}
